/* VCD dumping functions */
MOD_mkStretchIplFileTb & mkStretchIplFileTb_backing(tSimStateHdl simHdl)
{
  static MOD_mkStretchIplFileTb *instance = NULL;
  if (instance == NULL)
  {
    vcd_set_backing_instance(simHdl, true);
    instance = new MOD_mkStretchIplFileTb(simHdl, "top", NULL);
    vcd_set_backing_instance(simHdl, false);
  }
  return *instance;
}
